import numpy as np
from collections import Counter
s=open('relaxed.xyz').readlines(); p=np.array([[float(x) for x in l.split()[1:]] for l in s[2:]])
print(Counter(l.split()[0] for l in s[2:]))
for n in [2,11,18,49,50,52,54,56]:print('Ir -',n,np.linalg.norm(p[29]-p[n]))
for a,b in np.load('connect.npz')['bonds']:
 d=np.linalg.norm(p[a]-p[b]);
 if d>1.8 and a!=29 and b!=29:print('long?',a,b,d)
for n,cs in [(2,[1,3]),(11,[1,12]),(18,[13,17])]:
 print('N',n)
 for c in cs:
  a=p[c]-p[n]; b=p[29]-p[n]; print(c, np.degrees(np.arccos(a@b/np.linalg.norm(a)/np.linalg.norm(b))))
cp=p[[49,50,52,54,56]]; ctr=cp.mean(0);v=ctr-p[29]
print('Cp center to Ir',np.linalg.norm(v));print('Ir-N to cp-ctr angles:')
for i in [2,11,18]:
 w=p[i]-p[29];print(i,np.degrees(np.arccos(v@w/np.linalg.norm(v)/np.linalg.norm(w))))
